/**
 * navi-connect stations (PROTOCOL §18): radio and autoplay, generated by the hub.
 *
 * Shared by the main-process client (`main/features/core/station`), the preload bridge and the
 * renderer (`renderer/features/player/station`). The main process normalizes the hub's answers
 * into these once, so nothing downstream reads raw JSON.
 *
 * Words: in the UI a seeded station is a *radio* and the seedless one is *Your mix*. `station` is
 * the noun in code and on the wire only ("Station" is Subsonic internet radio in this app).
 */

/** The answer to `start` and `next`, normalized. Fields `next` does not carry are left empty. */
export interface StationAnswer {
    /** `start` only: whether `bindSession` bound the session. Null when the hub did not say. */
    bound: boolean | null;
    character: StationCharacterId;
    engine: null | StationEngine;
    exhausted: boolean;
    /** `start` only. */
    name: string;
    /** As the hub echoed it; null from a hub that does not. */
    origin: null | StationOrigin;
    partial: boolean;
    rev: number;
    /** `start` only. */
    seed: null | StationSeed;
    seq: number;
    /** `next` only: another device already topped this station up; `tracks` is empty. */
    servedElsewhere: boolean;
    stationId: string;
    /**
     * Someone picked Off (a `stop` signal): the station serves nothing until a character is
     * picked again, for every device. Null from a hub that does not say.
     */
    stopped: boolean | null;
    tracks: StationTrack[];
}

/** `GET /sonic/station/characters`: the probe and the shared catalogue. */
export interface StationCatalog {
    available: boolean;
    characters: StationCharacter[];
    configured: boolean;
    default: StationCharacterId;
    engine: null | StationEngine;
}

/** One row of `GET /sonic/station/characters`. */
export interface StationCharacter {
    description: string;
    id: StationCharacterId;
    label: string;
    /** The old MoodCharacter name this character replaces. */
    legacy: string;
}

/** The three characters, in the old preset order (EchoMatch / SteadyVibes / TransitionMaestro). */
export type StationCharacterId = 'balanced' | 'close' | 'explore';

/** What answered: AudioMuse (tier2), Navidrome's similar-songs agent (tier1), or nothing. */
export type StationEngine = 'tier1' | 'tier2';

export interface StationNextBody {
    after: number;
    count?: number;
    deviceId?: string;
    exclude?: string[];
    stationId: string;
}

/**
 * What a station was started as. A `radio` keeps going whether or not Autoplay is on; a
 * `continue` (autoplay carrying on a queue no station built) runs only while Autoplay is on.
 */
export type StationOrigin = 'continue' | 'radio';

/**
 * Every station call's result. `status` 0 means the request never got an HTTP answer (no hub
 * configured, unreachable, timed out). `code` is the hub's machine-readable reason
 * (`bad_seed`, `seed_unknown`, `session_bound`, `station_unknown`, ...). `fallback` is the 503
 * that says no tier is usable. `stationId` rides on a 409 `session_bound`.
 */
export interface StationResult<T> {
    code?: string;
    data: null | T;
    error: string;
    fallback?: boolean;
    ok: boolean;
    stationId?: string;
    status: number;
}

export type StationSeed =
    | { ids: string[]; kind: 'track'; name?: string }
    | { ids: string[]; kind: 'tracks'; name?: string }
    | { kind: 'yourMix'; name?: string };

export interface StationSignalAnswer {
    applied: boolean;
    ignored?: string;
    rev: number;
}

export interface StationSignalBody {
    kind: StationSignalKind;
    stationId: string;
    trackId?: string;
    value?: StationCharacterId;
}

export type StationSignalKind =
    | 'character'
    | 'dislike'
    | 'like'
    | 'played'
    | 'skip'
    | 'stop'
    | 'unlike';

export interface StationStartBody {
    bindSession?: string;
    character?: StationCharacterId;
    count?: number;
    deviceId?: string;
    exclude?: string[];
    /** Why it starts: a radio the user asked for, or autoplay continuing a queue no station built. */
    origin?: StationOrigin;
    seed: StationSeed;
}

/** One served track. `why`/`rank` say which source admitted it; the client only displays. */
export interface StationTrack {
    album: string;
    artist: string;
    id: string;
    rank?: number;
    title: string;
    why?: string;
}
